import java.util.*;
import java.io.*;

public class Main {
    static class BitSet128 {
        long low;
        long high;

        public BitSet128() {
            this.low = 0L;
            this.high = 0L;
        }

        public BitSet128(BitSet128 other) {
            this.low = other.low;
            this.high = other.high;
        }

        public void set(int index) {
            if (index < 64) {
                low |= 1L << index;
            } else {
                high |= 1L << (index - 64);
            }
        }

        public boolean get(int index) {
            if (index < 64) {
                return ((low >>> index) & 1L) != 0;
            } else {
                return ((high >>> (index - 64)) & 1L) != 0;
            }
        }

        public BitSet128 clone() {
            return new BitSet128(this);
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof BitSet128)) return false;
            BitSet128 other = (BitSet128) o;
            return this.low == other.low && this.high == other.high;
        }

        public int hashCode() {
            return Objects.hash(low, high);
        }
    }

    static final int mod = 1000000007;
    static final int inv = 570000004;

    static int add(int a, int b) {
        int res = a + b;
        return res >= mod ? res - mod : res;
    }

    static int sub(int a, int b) {
        int res = a - b;
        return res < 0 ? res + mod : res;
    }

    static int mul(int a, int b) {
        return (int)((long)a * b % mod);
    }

    static Map<BitSet128, Integer> name = new HashMap<>();
    static int n, dfn;
    static int[][] son;
    static int[] p = new int[7];
    static int[][] q = new int[7][128];
    static int[][] dp = new int[8][65536];

    static int dfs(BitSet128 s) {
        if (name.containsKey(s))
            return name.get(s);
        int ret = dfn++;
        name.put(s, ret);
        son[ret] = new int[1 << n];
        for (int i = 0; i < (1 << n); i++) {
            BitSet128 t = s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!t.get(j)) {
                    for (int k = i & j; k != 0; k ^= k & -k) {
                        int index = j ^ (k & -k);
                        if (s.get(index)) {
                            t.set(j);
                            break;
                        }
                    }
                }
            }
            son[ret][i] = dfs(t);
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        n = Integer.parseInt(br.readLine());
        dfn = 0;
        name.clear();
        son = new int[1 << 16][];
        BitSet128 start = new BitSet128();
        start.set(1);
        int rootIndex = dfs(start);

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                p[i] = Integer.parseInt(st.nextToken());
                p[i] = mul(p[i], inv);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) != 0) {
                        q[i][j] = mul(q[i][j], p[k]);
                    } else {
                        q[i][j] = mul(q[i][j], sub(1, p[k]));
                    }
                }
            }
        }

        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], 0);
        }
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < dfn; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int nextState = son[j][k];
                    dp[i + 1][nextState] = add(dp[i + 1][nextState], mul(dp[i][j], q[i][k]));
                }
            }
        }

        BitSet128 res = new BitSet128();
        for (int i = 0; i < (1 << n); i++) {
            res.set(i);
        }
        int answer = dp[n][name.get(res)];
        System.out.println(answer);
    }
}
